"""Authored behavioral probes and compiling defects; no source prose is replaced here."""
S={}
def chapter(n, repairs, rows):
    assert len(rows)==8,(n,len(rows))
    S[n]={'repairs':repairs,'rows':rows}
def r(label,body,expected,why): return dict(label=label,body=body,expected=expected,why=why)
chapter(1,[('Restore the stored-record contract','return "stored " +','return "" +','ArchiveJob must add the stored prefix once, after validating text and obtaining a product.'),('Repair the length product','std::to_string(text.size()) + ":"','std::to_string(text.size() + 1) + ":"','LengthRecord counts the bytes in the supplied string, not a terminating zero.')],[
r('Text product','TextJob j; return j.run("go");','"stored text:go"','TextJob selects TextRecord; the common run method adds stored.'),
r('Bracket product','BracketJob j; return j.run("go");','"stored [go]"','Only the product formatting changes; the common prefix remains.'),
r('Length product','LengthJob j; return j.run("go");','"stored 2:go"','The string go has two bytes. The product supplies 2:go.'),
r('Polymorphic creator','LengthJob j; const ArchiveJob& b=j; return b.run("a b");','"stored 3:a b"','The reference keeps the dynamic creator type, including the embedded space in the count.'),
r('Empty input','return dpx_rejects<std::invalid_argument>([]{ TextJob{}.run(""); });','true','Validation rejects empty input before construction of a product.'),
r('Upper bound','return static_cast<int>(LengthJob{}.run(std::string(20,\'z\')).size());','30','The stored prefix uses seven bytes and 20: uses three; twenty payload bytes make thirty.'),
r('Beyond bound','return dpx_rejects<std::invalid_argument>([]{ BracketJob{}.run(std::string(21,\'z\')); });','true','A different creator cannot bypass the common twenty-byte limit.'),
r('Missing product','return dpx_rejects<std::logic_error>([]{ EmptyJob{}.run("ok"); });','true','A null factory result violates the creator contract; it is checked before dereference.')])
chapter(2,[('Restore framed family consistency','return std::make_unique<FramedDecoder>();','return std::make_unique<PlainDecoder>();','A factory must return an encoder and decoder that agree on the wire format.'),('Repair the tagged encoder','return "d=" + std::to_string(value);','return "d=" + std::to_string((value + 1) % 10);','The tagged encoder must preserve the digit, not advance it.')],[
r('Plain zero','PlainFactory f; return round_trip(f,0);','"0"','Plain products agree on the one-character format.'),r('Framed endpoint','FramedFactory f; return round_trip(f,9);','"[9]"','The matching decoder removes the frame and returns nine.'),r('Tagged middle','TaggedFactory f; return round_trip(f,4);','"d=4"','A tagged family preserves the same numeric value across encoding and decoding.'),r('Tagged endpoint','TaggedFactory f; return round_trip(f,9);','"d=9"','Nine is valid; ten is not part of this digit protocol.'),r('Cross-family input','return dpx_rejects<std::invalid_argument>([]{ PlainFactory f; f.decoder()->read("[2]"); });','true','A valid framed string is invalid for the plain decoder.'),r('Bad tagged length','return dpx_rejects<std::invalid_argument>([]{ TaggedFactory f; f.decoder()->read("d=44"); });','true','The tag requires exactly one digit after d=.'),r('Bad digit','return dpx_rejects<std::invalid_argument>([]{ TaggedFactory f; f.decoder()->read("d=q"); });','true','A letter cannot represent the required digit.'),r('Out of range','return dpx_rejects<std::invalid_argument>([]{ FramedFactory f; round_trip(f,10); });','true','The family does not enlarge the domain merely by adding brackets.')])
chapter(3,[('Restore total-duration validation','if (total > 90)','if (total > 120)','A Plan may contain at most ninety minutes, even when each individual session is valid.'),('Repair builder reset','title_.clear();','/* defect: title survives reset */','Reset must clear the name as well as the session list; existing Plan values stay independent.')],[
r('Two sessions','return PlanBuilder{}.named("Short").add(12).add(18).build().total();','30','The builder adds durations; it does not multiply by the number of sessions.'),r('Ninety-minute boundary','return PlanBuilder{}.named("Edge").add(60).add(30).build().total();','90','The upper total bound is inclusive.'),r('Too much total','return dpx_rejects<std::logic_error>([]{ PlanBuilder{}.named("Long").add(60).add(31).build(); });','true','Both sessions are valid alone, but their combined total exceeds ninety.'),r('No sessions','return dpx_rejects<std::logic_error>([]{ PlanBuilder{}.named("Empty").build(); });','true','Naming a draft does not make it a complete plan.'),r('Reset removes title','PlanBuilder b; b.named("Old").add(10); b.reset(); b.add(7); return dpx_rejects<std::logic_error>([&]{b.build();});','true','After reset, adding a session alone must not reuse the old name.'),r('Snapshot survives reset','PlanBuilder b; auto p=b.named("Old").add(12).build(); b.reset(); return p.total();','12','Plan owns copied values, so clearing the builder does not clear an earlier plan.'),r('New plan after reset','PlanBuilder b; b.named("Old").add(12); b.reset(); return b.named("New").add(7).build().total();','7','Neither the old title nor old durations belong to the new draft.'),r('Session lower bound','return dpx_rejects<std::invalid_argument>([]{ PlanBuilder{}.add(0); });','true','A zero-minute activity is outside the builder contract.')])
chapter(4,[('Repair cloned text preservation','return std::make_unique<TextCue>(*this);','return std::make_unique<TextCue>("wrong");','Cloning must copy the existing text and keep the concrete kind.'),('Repair the boxed deep copy','std::make_unique<std::string>(*other.name_)','std::make_unique<std::string>("wrong")','A new owning allocation must receive the source value; a fresh but unrelated value is not a clone.')],[
r('Text clone','TextCue a("Cue"); return a.clone()->text();','"text:Cue"','The virtual clone preserves both the TextCue kind and its state.'),r('Text independence','TextCue a("Cue"); auto b=a.clone(); b->rename("Next"); return a.text();','"text:Cue"','Changing the clone cannot change the original value.'),r('List clone edit','ListCue a({"A","B"}); auto b=a.clone(); b->rename("C"); return b->text();','"list:C;B;"','Only the first list entry is renamed; the second is copied intact.'),r('Original list remains','ListCue a({"A","B"}); auto b=a.clone(); b->rename("C"); return a.text();','"list:A;B;"','The copied vector and strings are independent values.'),r('Box clone state','BoxCue a("Open"); return a.clone()->text();','"box:Open"','A fresh string allocation must contain Open, not a default label.'),r('Box lifetime','auto a=std::make_unique<BoxCue>("One"); auto b=a->clone(); a.reset(); return b->text();','"box:One"','Destroying the original does not destroy the clone’s separate string.'),r('Invalid box edit','BoxCue a("Keep"); const bool bad=dpx_rejects<std::invalid_argument>([&]{a.rename("");}); return bad && a.text()=="box:Keep";','true','Validation precedes assignment so rejection preserves the previous state.'),r('Empty list','return dpx_rejects<std::invalid_argument>([]{ListCue a(std::vector<std::string>{});});','true','There must be a first list entry for rename to replace.')])
chapter(5,[('Restore ticket boundary','if (next_ > 3)','if (next_ > 2)','The third ticket is valid; only later requests are exhausted.'),('Repair dependency injection','return source.take();','(void)source; return TicketDispenser::instance().take();','admit must use its supplied source; using the global source silently couples independent clients.')],[
r('First local ticket','LocalTickets a; return admit(a);','1','A new local source starts at one.'),r('Second local ticket','LocalTickets a; a.take(); return a.take();','2','Successful calls advance the source once.'),r('Third local ticket','LocalTickets a; a.take(); a.take(); return a.take();','3','Three is still within the inclusive ticket limit.'),r('Exhaustion','LocalTickets a; a.take(); a.take(); a.take(); return dpx_rejects<std::out_of_range>([&]{a.take();});','true','After ticket three, the source rejects requests rather than wrapping.'),r('Injected source identity','LocalTickets a; a.take(); return admit(a);','2','admit must continue the supplied source, whose first ticket was already consumed.'),r('Independent clients','LocalTickets a,b; admit(a); return admit(b);','1','A separate local object has its own counter even after another client runs.'),r('Singleton identity','return &TicketDispenser::instance()==&TicketDispenser::instance();','true','Both references name the same function-local static object.'),r('Failed calls preserve exhaustion','LocalTickets a; a.take(); a.take(); a.take(); dpx_rejects<std::out_of_range>([&]{a.take();}); return dpx_rejects<std::out_of_range>([&]{a.take();});','true','Failure does not reset or restart the ticket sequence.')])
chapter(6,[('Repair the unit conversion','raw / 1000.0 - offset_','raw / 1000 - offset_','Use floating-point division so partial grams survive conversion.'),('Repair calibration direction','raw / 1000.0 - offset_','raw / 1000.0 + offset_','The calibrated reading subtracts the offset in grams after conversion.')],[
r('Fraction survives','LegacyScale d(1750); ScaleAdapter a(d); return std::abs(a.grams()-1.75)<1e-9;','true','The 750 milligrams are three quarters of a gram, not discarded.'),r('Exact light boundary','LegacyScale d(2000); ScaleAdapter a(d); return light_enough(a);','true','The client accepts two grams exactly.'),r('Just above light boundary','LegacyScale d(2001); ScaleAdapter a(d); return light_enough(a);','false','A reading of 2.001 grams exceeds the client limit.'),r('Device failure','LegacyScale d(-1); ScaleAdapter a(d); return dpx_rejects<std::runtime_error>([&]{a.grams();});','true','Negative raw values are device errors, not negative mass.'),r('Subtract offset','LegacyScale d(1750); ScaleAdapter a(d,0.5); return std::abs(a.grams()-1.25)<1e-9;','true','Convert to 1.75 grams, then subtract 0.5 grams.'),r('Exactly zero after calibration','LegacyScale d(500); ScaleAdapter a(d,0.5); return a.grams()==0.0;','true','Zero is a valid corrected reading.'),r('Offset too large','LegacyScale d(500); ScaleAdapter a(d,0.75); return dpx_rejects<std::runtime_error>([&]{a.grams();});','true','A negative corrected reading violates the adapter’s output contract.'),r('Negative offset rejected','LegacyScale d(500); return dpx_rejects<std::invalid_argument>([&]{ScaleAdapter a(d,-0.5);});','true','This calibration model only accepts nonnegative offsets.')])
chapter(7,[('Repair report policy boundary','n > 5 ?','n >= 5 ?','Five remains normal; only a larger count is high.'),('Repair CSV formatting','return name + "," +','return name + ";" +','Csv changes representation using a comma while the report keeps responsibility for meaning.')],[
r('Plain count','Plain w; return CountReport(w).render(3);','"count=3"','The report supplies count and three; Plain joins them with an equals sign.'),r('Bracket warning boundary','Brackets w; return WarningReport(w).render(5);','"[normal:5]"','The warning rule chooses normal before the writer adds brackets.'),r('High warning','Plain w; return WarningReport(w).render(6);','"high=6"','Six is above the warning threshold.'),r('Negative report input','Plain w; return dpx_rejects<std::invalid_argument>([&]{CountReport(w).render(-1);});','true','All report forms retain the common nonnegative-count contract.'),r('CSV count','Csv w; return CountReport(w).render(3);','"count,3"','Adding a writer should not require a new CountReport subclass.'),r('CSV warning','Csv w; return WarningReport(w).render(5);','"normal,5"','The same warning rule can use the new representation.'),r('CSV zero','Csv w; return CountReport(w).render(0);','"count,0"','Zero remains meaningful; the writer does not reject it.'),r('Shared writer, distinct reports','Csv w; CountReport a(w); WarningReport b(w); return a.render(8)+"|"+b.render(8);','"count,8|high,8"','One borrowed writer formats two independent report meanings.')])
chapter(8,[('Restore recursive minutes','total += n;','total += 0;','A group must add each child duration once, including nested groups.'),('Repair leaf counting','std::size_t steps() const override { return 1; }','std::size_t steps() const override { return 0; }','A Step is one leaf even when its duration is zero.')],[
r('One leaf duration','return Step(17).minutes();','17','The leaf reports its own duration.'),r('Group sum','Children c; c.push_back(std::make_unique<Step>(7)); c.push_back(std::make_unique<Step>(8)); return Group(std::move(c)).minutes();','15','The parent asks both children for their subtotal and adds them.'),r('Empty group duration','return Group(Children{}).minutes();','0','The sum over an empty child list is zero.'),r('Budget overflow','return dpx_rejects<std::overflow_error>([]{Children c; c.push_back(std::make_unique<Step>(9999)); c.push_back(std::make_unique<Step>(2)); Group(std::move(c)).minutes();});','true','The group rejects 10001 before accepting a total over its budget.'),r('Zero-minute leaf count','return static_cast<int>(Step(0).steps());','1','Leaf count describes structure rather than duration.'),r('Two leaf count','Children c; c.push_back(std::make_unique<Step>(0)); c.push_back(std::make_unique<Step>(8)); return static_cast<int>(Group(std::move(c)).steps());','2','Both leaves count, including the zero-duration one.'),r('Empty group leaf count','return static_cast<int>(Group(Children{}).steps());','0','An empty group contains no leaf activities.'),r('Nested structure','Children a; a.push_back(std::make_unique<Step>(4)); Children b; b.push_back(std::make_unique<Group>(std::move(a))); b.push_back(std::make_unique<Step>(6)); Group g(std::move(b)); return g.minutes()==10 && g.steps()==2;','true','An internal group is not an extra leaf; recursion counts its children.')])
chapter(9,[('Repair prefix order','const auto result = prefix_ + body;','const auto result = body + prefix_;','A Prefix adds its text before the entire inner result.'),('Repair suffix order','return inner_->text() + suffix_;','return suffix_ + inner_->text();','A Suffix adds text after its inner result; wrapper order remains observable.')],[
r('Prefix text','return Prefix(std::make_unique<Plain>("ok"),"!").text();','"!ok"','The prefix belongs before the inner message.'),r('Limit outer result','return Limit(std::make_unique<Prefix>(std::make_unique<Plain>("ready"),"!"),3).text();','"!re"','The outer limit trims the already-prefixed string.'),r('Prefix outside limit','return Prefix(std::make_unique<Limit>(std::make_unique<Plain>("ready"),3),"!").text();','"!rea"','The inner limit trims ready first, then the prefix adds one byte.'),r('Zero limit','return Limit(std::make_unique<Plain>("abc"),0).text();','""','A zero-length prefix of a string is empty.'),r('Suffix text','return Suffix(std::make_unique<Plain>("ok"),"!").text();','"ok!"','The suffix belongs after the inner message.'),r('Suffix outside limit','return Suffix(std::make_unique<Limit>(std::make_unique<Plain>("ready"),3),"!").text();','"rea!"','The outer suffix is not subject to the inner limit.'),r('Limit outside suffix','return Limit(std::make_unique<Suffix>(std::make_unique<Plain>("ready"),"!"),5).text();','"ready"','The suffix exists in the inner result but is cut off by the outer limit.'),r('No inner message','return dpx_rejects<std::invalid_argument>([]{Suffix s(nullptr,"!");});','true','A wrapper requires a live owned inner message.')])
chapter(10,[('Repair complete-token parsing','result.ec != std::errc{} || result.ptr != end','result.ec != std::errc{}','A number prefix followed by junk is not a valid integer token.'),('Repair fractional means','static_cast<double>(result.total) / result.count','result.total / result.count','Convert before division, or integer arithmetic truncates the mean.')],[
r('Total and count','auto s=Importer{}.run("2 7"); return s.total==9 && s.count==2;','true','The facade coordinates parse, validation and summary in order.'),r('Trailing junk','return dpx_rejects<std::invalid_argument>([]{Importer{}.run("7x");});','true','Parsing must consume the whole token, not just its numeric prefix.'),r('Fractional token','return dpx_rejects<std::invalid_argument>([]{Importer{}.run("7.5");});','true','The input language accepts integers only.'),r('Range boundary','return Importer{}.run("-100 100").total;','0','Both endpoints are valid, and their sum is zero.'),r('Fractional average','return Importer{}.mean("2 7")==4.5;','true','Nine divided by two must be floating-point division.'),r('Negative average','return Importer{}.mean("-2 -7")==-4.5;','true','Negative fractional values must not truncate toward zero either.'),r('Single value mean','return Importer{}.mean("8")==8.0;','true','A one-value batch has that same mean.'),r('Empty mean','return dpx_rejects<std::invalid_argument>([]{Importer{}.mean("");});','true','The facade validates before division, so an empty batch cannot cause division by zero.')])
chapter(11,[('Repair the shared-state key','const Key key{name, size};','const Key key{name, 1};','All intrinsic fields must participate in the pool key; different sizes cannot alias.'),('Repair pool clearing','void clear() { styles_.clear(); }','void clear() { /* defect: keeps entries */ }','Clear releases the pool’s references without destroying styles still owned by marks.')],[
r('Same style identity','StylePool p; return p.get("dash",8)==p.get("dash",8);','true','Within the pool, the same full key reuses one immutable style.'),r('Different size identity','StylePool p; return p.get("dash",8)==p.get("dash",9);','false','Size is part of shared state; different sizes require different styles.'),r('Different name identity','StylePool p; return p.get("dot",8)==p.get("dash",8);','false','Matching size alone is not enough to share.'),r('Position stays local','StylePool p; Mark a(p.get("dot",8),2),b(p.get("dot",8),7); return a.draw()+"|"+b.draw();','"dot/8@2|dot/8@7"','Position is extrinsic state stored in each Mark, not in Style.'),r('Clear count','StylePool p; p.get("dot",8); p.clear(); return static_cast<int>(p.count());','0','The pool must have no retained entries after clearing.'),r('Old client survives clear','StylePool p; Mark a(p.get("dot",8),2); p.clear(); return a.draw();','"dot/8@2"','The Mark’s shared_ptr keeps its immutable style alive.'),r('New identity after clear','StylePool p; auto a=p.get("dot",8); p.clear(); return a==p.get("dot",8);','false','The old style still exists, but the emptied pool creates a new object for the same value.'),r('Invalid size','return dpx_rejects<std::invalid_argument>([]{StylePool p; p.get("dot",101);});','true','The size domain remains one through one hundred.')])
chapter(12,[('Repair cache invalidation','void invalidate() { cached_.reset(); }','void invalidate() { /* defect: cache survives */ }','Invalidate must remove the cached value while retaining the real service.'),('Repair explicit refresh','        invalidate();\n        return opening();','        return opening();','Refresh must discard a permitted cached value and read the source once.')],[
r('Lazy construction','Source s; HoursProxy p(s); return p.loaded();','false','Constructing the proxy alone does not construct the real service.'),r('First read','Source s; HoursProxy p(s); p.opening(); return s.reads;','1','A cache miss creates the service and reads once.'),r('Stale cache retained','Source s; HoursProxy p(s); p.opening(); s.hour=14; return p.opening();','8','Changing the source does not silently invalidate the cache.'),r('Invalidate then read','Source s; HoursProxy p(s); p.opening(); s.hour=14; p.invalidate(); return p.opening();','14','The explicit invalidation makes the next opening a cache miss.'),r('Refresh updates','Source s; HoursProxy p(s); p.opening(); s.hour=15; return p.refresh();','15','Refresh asks for a new reading even if a value is already cached.'),r('Refresh read count','Source s; HoursProxy p(s); p.opening(); p.refresh(); return s.reads;','2','One initial read and one explicit refresh produce two source reads.'),r('Revoked cached access','Source s; HoursProxy p(s); p.opening(); p.allow(false); return dpx_rejects<std::runtime_error>([&]{p.opening();});','true','Permission is checked before returning even a cached value.'),r('Denied refresh preserves cache','Source s; HoursProxy p(s); p.opening(); s.hour=15; p.allow(false); const bool bad=dpx_rejects<std::runtime_error>([&]{p.refresh();}); p.allow(true); return bad && p.opening()==8 && s.reads==1;','true','Rejected refresh must not invalidate the previously valid cache or perform I/O.')])
chapter(13,[('Repair page validation','job.pages < 1 || job.pages > 1000','job.pages < 0 || job.pages > 1000','Reject a zero-page request before any handler can accept it.'),('Repair express boundary','job.pages <= 5','job.pages < 5','Five-page reports still belong to the express desk when it is first.')],[
r('Specific handler first','return route({"label",3},{label_rule,general_rule});','"label desk"','The first handler that returns a value wins.'),r('Broad handler first','return route({"label",3},{general_rule,label_rule});','"general desk"','Reordering overlapping rules changes the chosen destination.'),r('Invalid zero pages','return route({"label",0},{label_rule});','"rejected"','Validation happens before routing, so no desk gets an invalid request.'),r('Empty chain','return route({"report",1},{});','"unhandled"','No handlers means a valid request has no destination.'),r('Express endpoint','return route({"report",5},{express_rule,general_rule});','"express desk"','Five is within the express limit.'),r('Over express limit','return route({"report",6},{express_rule,general_rule});','"general desk"','Express declines and the next rule accepts.'),r('Express cannot steal labels','return route({"label",2},{express_rule,label_rule});','"label desk"','The express rule must check format as well as size.'),r('Unknown format','return route({"archive",2},{express_rule,general_rule});','"unhandled"','Neither handler accepts the archive format.')])
chapter(14,[('Repair undo snapshot','before_ = marker_.position();','before_ = target_;','Save the receiver’s old position before executing, not the destination.'),('Repair batch rollback','batch[applied]->undo();','/* defect: skip undo */','On the specified out-of-range failure, undo successful commands in reverse order.')],[
r('Execute target','Marker m; Move c(m,4); c.execute(); return m.position();','4','Execution changes the receiver to the requested valid position.'),r('Undo original','Marker m; m.set(2); Move c(m,4); c.execute(); c.undo(); return m.position();','2','Undo must restore the position captured before execution.'),r('Repeat rejected','Marker m; Move c(m,4); c.execute(); return dpx_rejects<std::logic_error>([&]{c.execute();});','true','An already applied Move cannot be applied twice without undo.'),r('Undo unused rejected','Marker m; Move c(m,4); return dpx_rejects<std::logic_error>([&]{c.undo();});','true','An unused command has no successful change to reverse.'),r('Failed batch restores receiver','Marker m; std::vector<std::unique_ptr<Command>> b; b.push_back(std::make_unique<Move>(m,4)); b.push_back(std::make_unique<Move>(m,11)); const bool ok=run_batch(b); return !ok && m.position()==0;','true','The first move must be undone after the second violates the range.'),r('Reverse rollback order','Marker m; m.set(1); std::vector<std::unique_ptr<Command>> b; for(int x:{3,7,11}) b.push_back(std::make_unique<Move>(m,x)); run_batch(b); return m.position();','1','Undo seven to three, then three to one; forward undo would leave the wrong value.'),r('Successful batch','Marker m; std::vector<std::unique_ptr<Command>> b; b.push_back(std::make_unique<Move>(m,4)); return run_batch(b) && m.position()==4;','true','Successful commands remain applied; success must not trigger rollback.'),r('Empty batch','std::vector<std::unique_ptr<Command>> b; return run_batch(b);','true','An empty batch succeeds without changing any receiver.')])
chapter(15,[('Repair forward cursor advancement','++index_;','/* defect: never advances */','A successful next moves the cursor to the following index.'),('Repair reverse traversal','--remaining_;','remaining_ = 0;','Reverse next consumes one element rather than ending the entire traversal.')],[
r('Forward first','Readings r; r.append(3); r.append(8); return r.cursor().read();','3','A new cursor starts at the first stored element.'),r('Forward second','Readings r; r.append(3); r.append(8); auto c=r.cursor(); c.next(); return c.read();','8','One next advances by one element.'),r('Independent cursor copy','Readings r; r.append(3); r.append(8); auto a=r.cursor(),b=a; a.next(); return b.read();','3','Copying a cursor copies its position; advancing one does not move the other.'),r('Stale forward cursor','Readings r; auto c=r.cursor(); r.append(3); return dpx_rejects<std::logic_error>([&]{c.done();});','true','Appending changes the owner’s version and invalidates the old view.'),r('Reverse first','Readings r; r.append(3); r.append(8); return r.reverse_cursor().read();','8','Reverse traversal starts at the last stored element.'),r('Reverse second','Readings r; r.append(3); r.append(8); auto c=r.reverse_cursor(); c.next(); return c.read();','3','One reverse step reaches the previous element, not the end yet.'),r('Empty reverse','Readings r; return r.reverse_cursor().done();','true','A zero-length collection has no reverse element to read.'),r('Stale reverse cursor','Readings r; r.append(3); auto c=r.reverse_cursor(); r.append(8); return dpx_rejects<std::logic_error>([&]{c.read();});','true','Reverse cursors obey the same owner-version rule as forward cursors.')])
chapter(16,[('Restore consent requirement','ready && accepted_ && !held_','ready && !held_','A filled name alone must not enable saving; consent is also required.'),('Repair hold coordination','void hold(bool value) { held_ = value; changed(); }','void hold(bool value) { held_ = value; }','Changing hold must immediately recompute the button state.')],[
r('Initial form','Form f; return f.enabled();','false','The empty name and missing consent both block saving.'),r('Name alone','Form f; f.name("Ada"); return f.enabled();','false','Entering a name does not imply consent.'),r('Name and consent','Form f; f.name("Ada"); f.accept(true); return f.enabled();','true','Both required inputs permit the button when no hold applies.'),r('Revoked consent','Form f; f.name("Ada"); f.accept(true); f.accept(false); return f.submit();','false','The mediator recomputes permission when consent changes.'),r('Hold blocks ready form','Form f; f.name("Ada"); f.accept(true); f.hold(true); return f.enabled();','false','Hold overrides otherwise valid inputs.'),r('Hold blocks count change','Form f; f.name("Ada"); f.accept(true); f.hold(true); f.submit(); return f.saved();','0','A blocked submit does not increment the successful-save count.'),r('Lift hold restores readiness','Form f; f.name("Ada"); f.accept(true); f.hold(true); f.hold(false); return f.submit();','true','Lifting hold recomputes all conditions and allows a valid form again.'),r('Lift cannot replace missing name','Form f; f.accept(true); f.hold(true); f.hold(false); return f.enabled();','false','Clearing hold is not an unconditional enable operation.')])
chapter(17,[('Repair saved lower bound','low_ = saved.low_;','low_ = saved.high_;','Restore must copy both saved endpoints to their matching fields.'),('Repair bounded history','proposed.size() == 3','proposed.size() == 2','The history keeps the three most recent snapshots, not two.')],[
r('Restore interval','Selection s; s.set(3,8); auto p=s.save(); s.set(20,30); s.restore(p); return s.low();','3','The saved lower endpoint is three, independent of later edits.'),r('Restore upper bound','Selection s; s.set(3,8); auto p=s.save(); s.set(20,30); s.restore(p); return s.high();','8','Both endpoints return to their saved values.'),r('Invalid edit preserves state','Selection s; s.set(3,8); const bool bad=dpx_rejects<std::out_of_range>([&]{s.set(9,2);}); return bad && s.low()==3 && s.high()==8;','true','Check the pair before changing either field.'),r('Reusable structural snapshot','Selection a,b; a.set(4,9); b.restore(a.save()); return b.low()==4 && b.high()==9;','true','This snapshot represents an interval value and can restore another Selection.'),r('Keep three entries','Selection s; History h(s); for(int i=1;i<=3;++i){s.set(i,i+1); h.remember();} int n=0; while(h.undo())++n; return n;','3','Three snapshots all fit before eviction begins.'),r('Evict oldest','Selection s; History h(s); for(int i=1;i<=4;++i){s.set(i,i+1); h.remember();} while(h.undo()){} return s.low();','2','After four remembers, the surviving snapshots are two, three and four.'),r('Empty undo','Selection s; History h(s); return h.undo();','false','No snapshot is a normal false result, not a fabricated restore.'),r('Undo consumes entry','Selection s; History h(s); h.remember(); h.undo(); return h.undo();','false','A successfully restored entry is removed from the history.')])
chapter(18,[('Repair exception cleanup','~Reset() { flag = false; }','~Reset() { /* defect: busy forever */ }','The publishing flag must clear on every exit, including a throwing callback.'),('Repair targeted unsubscribe','return !live || live == listener;','return !live || live != listener;','Unsubscribe removes the matching listener and expired registrations while keeping other live listeners.')],[
r('Duplicate subscription','Feed f; auto a=std::make_shared<Total>(); f.subscribe(a); f.subscribe(a); f.publish(6); return a->sum;','6','Subscribing the same listener twice must not deliver twice.'),r('Second publication','Feed f; auto a=std::make_shared<Total>(); f.subscribe(a); f.publish(2); f.publish(3); return a->sum;','5','The busy flag must be cleared after the first successful delivery.'),r('Throw then recover','Feed f; auto a=std::make_shared<Total>(); f.subscribe(a); a->after=[]{throw std::runtime_error("hook");}; dpx_rejects<std::runtime_error>([&]{f.publish(2);}); a->after={}; f.publish(3); return a->sum;','5','The first sum change remains, but the scope guard allows the next publication.'),r('Bad value rejected','Feed f; return dpx_rejects<std::out_of_range>([&]{f.publish(101);});','true','Input validation prevents a value outside zero through one hundred.'),r('Remove selected listener','Feed f; auto a=std::make_shared<Total>(); f.subscribe(a); f.unsubscribe(a); f.publish(6); return a->sum;','0','A removed listener receives no subsequent values.'),r('Keep another listener','Feed f; auto a=std::make_shared<Total>(),b=std::make_shared<Total>(); f.subscribe(a); f.subscribe(b); f.unsubscribe(a); f.publish(6); return b->sum;','6','Removing one identity must not remove another live identity.'),r('Expired listener harmless','Feed f; {auto a=std::make_shared<Total>(); f.subscribe(a);} f.publish(6); return true;','true','Weak registrations can expire; locking failure means skip that listener.'),r('Reject mutation during delivery','Feed f; auto a=std::make_shared<Total>(); bool denied=false; f.subscribe(a); a->after=[&]{denied=dpx_rejects<std::logic_error>([&]{f.unsubscribe(a);});}; f.publish(1); return denied;','true','This chapter prohibits registration changes during publish; the snapshot-policy lab is a different contract.')])
chapter(19,[('Repair begin transition','if (event == Event::begin) { return std::make_unique<Active>(); }','if (event == Event::begin) { return std::make_unique<Done>(); }','Begin moves Idle to Active, not directly to Done.'),('Repair cancellation target','if (event == Event::cancel) { return std::make_unique<Idle>(); }','if (event == Event::cancel) { return std::make_unique<Done>(); }','Cancel from Active returns to Idle; it does not finish the session.')],[
r('Initial state','return Session{}.name();','"idle"','Each context starts with an owned Idle state.'),r('Begin state','Session s; s.send(Event::begin); return s.name();','"active"','The current Idle state proposes Active for begin.'),r('Finish sequence','Session s; s.send(Event::begin); s.send(Event::finish); return s.name();','"done"','Finish is meaningful after begin has made the context active.'),r('Invalid finish','Session s; return s.send(Event::finish);','false','Idle does not define a finish transition.'),r('Cancel active','Session s; s.send(Event::begin); s.send(Event::cancel); return s.name();','"idle"','Cancellation returns an active session to its starting state.'),r('Cancel idle rejected','Session s; return s.send(Event::cancel);','false','Cancellation is only permitted in Active.'),r('Cancel done rejected','Session s; s.send(Event::begin); s.send(Event::finish); return s.send(Event::cancel);','false','A finished session needs reset, not cancel.'),r('Restart after cancel','Session s; s.send(Event::begin); s.send(Event::cancel); s.send(Event::begin); return s.name();','"active"','The canceled context can begin a new active session.')])
